n.nl/ie_fcache/0000058892_Dolfje_Weerwolfje_0_0.jpg","checkedAt":"2026-10-31T19:30:08.773Z","http":200,"sha256":"069e0b17d7bc3b49d10101995633cd384d6037a57fdb4a5573bbb50a17485413","bytes":169961,"fact":"Dolfje Weerwolfje/Paul van Loon, white wolf and child in tree, Hugo van Look illustration, Leopold; NOT comicISBN9789025864118"},{"conflict":{"field":"Source Work heading","observed":"Dolfje Weerwolfje stripboek","decision":"Exact edition block/library are original novel; do not copy mixed Work heading or comic illustration credits."}}],"work_id":969100001,"language":"nl","bound_author_id":969300001,"text":"Dolfje ontdekt rond zijn zevende verjaardag dat hij bij volle maan in een weerwolfje verandert. Overdag is hij weer een gewone jongen, maar zijn nachtelijke gedaante levert vragen en onverwachte avonturen op. Zijn vriend Timmie probeert hem te helpen omgaan met het geheim. Dolfje wil niet buitengesloten worden en moet ontdekken wat deze verandering betekent voor zijn plaats binnen het gezin waarin hij opgroeit.","source_type":"official_catalog","source_name":"Bibliotheek.nl","source_url":"https://www.bibliotheek.nl/catalogus/titel.441426077.html/dolfje-weerwolfje/","provenance":"original_source_reviewed_summary"}},{"relation":"editions","ref":"edition:9789403183404","key":{"id":969200002},"before":{"id":969200002,"title":"Revolusi","isbn_10":null,"isbn_13":"9789403183404","work_id":969100002,"cover_id":null,"language":"nld","publisher":"De Bezige Bij","publish_date":null,"open_library_edition_id":"OL32046626M"},"after":{"id":969200002,"title":"Revolusi","isbn_10":null,"isbn_13":"9789403183404","work_id":969100002,"cover_id":null,"language":"nld","publisher":"De Bezige Bij","publish_date":null,"open_library_edition_id":"OL32046626M"}},{"relation":"catalog_edition_metadata","ref":"metadata:9789403183404","key":{"edition_id":969200002},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-10-31T19:31:00Z","review_batch":"nl-followup-003-20261031","evidence":[{"url":"https://metadata.isbn.nl/1364266/revolusi.html","checkedAt":"2026-10-31","fact":"Exact hardbackISBN, Dutch,2020date and cover"},{"url":"https://rozet.nl/catalogus/2005467/","checkedAt":"2026-10-31","fact":"Library exact Dutch printISBN/title/author,637pages"},{"url":"https://www.debezigebij.nl/boek/revolusi/ebook/9789403184401/","checkedAt":"2026-10-31","fact":"Publisher lists exact hardcover separately from ebook/audio/paperback; oral history and decolonisation facts"},{"url":"https://metadata.isbn.nl/ie_fcache/0000576411_Revolusi_0_0.jpg","checkedAt":"2026-10-31T19:30:10.584Z","http":200,"sha256":"e0f2747ab993fd7fe8e1763fb117703bc3b5cc254583dd1c9eb67a235dd41235","bytes":315038,"fact":"Revolusi/David Van Reybrouck, black branching motif/red title, De Bezige Bij mark; exact source hardback block"}],"edition_id":969200002,"work_id":969100002,"bound_author_id":969300002,"bound_title":"Revolusi","bound_language":"nld","bound_isbn13":"9789403183404","format":"hardcover","cover_url":"https://metadata.isbn.nl/ie_fcache/0000576411_Revolusi_0_0.jpg","card_cover_url":"https://metadata.isbn.nl/ie_fcache/0000576411_Revolusi_3_130_250_0_0.jpg","evidence_url":"https://metadata.isbn.nl/1364266/revolusi.html"}},{"relation":"catalog_work_descriptions","ref":"description:1170:nl","key":{"work_id":969100002,"language":"nl"},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-10-31T19:31:00Z","review_batch":"nl-followup-003-20261031","evidence":[{"url":"https://metadata.isbn.nl/1364266/revolusi.html","checkedAt":"2026-10-31","fact":"Exact hardbackISBN, Dutch,2020date and cover"},{"url":"https://rozet.nl/catalogus/2005467/","checkedAt":"2026-10-31","fact":"Library exact Dutch printISBN/title/author,637pages"},{"url":"https://www.debezigebij.nl/boek/revolusi/ebook/9789403184401/","checkedAt":"2026-10-31","fact":"Publisher lists exact hardcover separately from ebook/audio/paperback; oral history and decolonisation facts"},{"url":"https://metadata.isbn.nl/ie_fcache/0000576411_Revolusi_0_0.jpg","checkedAt":"2026-10-31T19:30:10.584Z","http":200,"sha256":"e0f2747ab993fd7fe8e1763fb117703bc3b5cc254583dd1c9eb67a235dd41235","bytes":315038,"fact":"Revolusi/David Van Reybrouck, black branching motif/red title, De Bezige Bij mark; exact source hardback block"}],"work_id":969100002,"language":"nl","bound_author_id":969300002,"text":"David Van Reybrouck onderzoekt de Indonesische onafhankelijkheidsstrijd vanuit de ervaringen van mensen die de gebeurtenissen meemaakten. Interviews en historisch onderzoek verbinden de Japanse bezetting, de dekolonisatieoorlog en de internationale verhoudingen na de Tweede Wereldoorlog. Het boek plaatst de strijd niet alleen tegenover de Nederlandse koloniale macht, maar ook binnen bredere veranderingen in Azië en daarbuiten. Zo laat het verschillende perspectieven op het ontstaan van een onafhankelijke staat naast elkaar zien.","source_type":"official_catalog","source_name":"Bureau ISBN","source_url":"https://metadata.isbn.nl/1364266/revolusi.html","provenance":"original_source_reviewed_summary"}},{"relation":"editions","ref":"edition:9789029091015","key":{"id":969200003},"before":{"id":969200003,"title":"Leven en laten leven","isbn_10":null,"isbn_13":"9789029091015","work_id":969100003,"cover_id":null,"language":"nld","publisher":"J.M. Meulenhoff","publish_date":null,"open_library_edition_id":"OL46531076M"},"after":{"id":969200003,"title":"Leven en laten leven","isbn_10":null,"isbn_13":"9789029091015","work_id":969100003,"cover_id":null,"language":"nld","publisher":"J.M. Meulenhoff","publish_date":null,"open_library_edition_id":"OL46531076M"}},{"relation":"catalog_edition_metadata","ref":"metadata:9789029091015","key":{"edition_id":969200003},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-10-31T19:31:00Z","review_batch":"nl-followup-003-20261031","evidence":[{"url":"https://metadata.isbn.nl/1070391/leven-en-laten-leven.html","checkedAt":"2026-10-31","fact":"Exact Dutch paperbackISBN/date/cover and Arthur Ophof premise; ebook has differentISBN"},{"url":"http://data.bibliotheken.nl/id/nbt/p417062516","checkedAt":"2026-10-30T14:42:05.387Z","fact":"Retained National Bibliography exact DutchISBN/author/title identity"},{"url":"https://www.lannoo.com/nl-be/literatuur-romans/leven-en-laten-leven-9789029091015","checkedAt":"2026-10-31","fact":"Indexed official publisher confirms same Arthur Ophof novel; no fresh direct fetch or cover transplant"},{"url":"https://metadata.isbn.nl/ie_fcache/0000524092_Leven_en_laten_leven_0_0.jpg","checkedAt":"2026-10-31T19:30:13.793Z","http":200,"sha256":"406b63af0c24be00dcef1560d644514aa02ffaa191569992fab47e950dc85061","bytes":236066,"fact":"Leven en laten leven/Hendrik Groen, bread/tea illustration, Meulenhoff; exact paperback block, not a diary cover"}],"edition_id":969200003,"work_id":969100003,"bound_author_id":969300003,"bound_title":"Leven en laten leven","bound_language":"nld","bound_isbn13":"9789029091015","format":"paperback","cover_url":"https://metadata.isbn.nl/ie_fcache/0000524092_Leven_en_laten_leven_0_0.jpg","card_cover_url":null,"evidence_url":"https://metadata.isbn.nl/1070391/leven-en-laten-leven.html"}},{"relation":"catalog_work_descriptions","ref":"description:1182:nl","key":{"work_id":969100003,"language":"nl"},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-10-31T19:31:00Z","review_batch":"nl-followup-003-20261031","evidence":[{"url":"https://metadata.isbn.nl/1070391/leven-en-laten-leven.html","checkedAt":"2026-10-31","fact":"Exact Dutch paperbackISBN/date/cover and Arthur Ophof premise; ebook has differentISBN"},{"url":"http://data.bibliotheken.nl/id/nbt/p417062516","checkedAt":"2026-10-30T14:42:05.387Z","fact":"Retained National Bibliography exact DutchISBN/author/title identity"},{"url":"https://www.lannoo.com/nl-be/literatuur-romans/leven-en-laten-leven-9789029091015","checkedAt":"2026-10-31","fact":"Indexed official publisher confirms same Arthur Ophof novel; no fresh direct fetch or cover transplant"},{"url":"https://metadata.isbn.nl/ie_fcache/0000524092_Leven_en_laten_leven_0_0.jpg","checkedAt":"2026-10-31T19:30:13.793Z","http":200,"sha256":"406b63af0c24be00dcef1560d644514aa02ffaa191569992fab47e950dc85061","bytes":236066,"fact":"Leven en laten leven/Hendrik Groen, bread/tea illustration, Meulenhoff; exact paperback block, not a diary cover"}],"work_id":969100003,"language":"nl","bound_author_id":969300003,"text":"Arthur Ophof nadert de vijftig en merkt hoe weinig zijn dagelijkse bestaan lijkt op de reizen en avonturen waarvan hij droomde. Het woon-werkverkeer en een vastgelopen huwelijk bepalen zijn dagen; afspraken met vrienden bieden nog afwisseling. Wanneer hij zijn baan verliest en een ontslagvergoeding krijgt, ontstaat onverwacht ruimte voor verandering. Arthur gaat nadenken over een nieuw begin, maar moet ook onder ogen zien wat hij daarvoor achter zich zou laten.","source_type":"official_catalog","source_name":"Bureau ISBN","source_url":"https://metadata.isbn.nl/1070391/leven-en-laten-leven.html","provenance":"original_source_reviewed_summary"}},{"relation":"editions","ref":"edition:9789025440374","key":{"id":969200004},"before":{"id":969200004,"title":"Alles wat er was","isbn_10":null,"isbn_13":"9789025440374","work_id":969100004,"cover_id":null,"language":"nld","publisher":"Atlas Contact","publish_date":null,"open_library_edition_id":"OL30959815M"},"after":{"id":969200004,"title":"Alles wat er was","isbn_10":null,"isbn_13":"9789025440374","work_id":969100004,"cover_id":null,"language":"nld","publisher":"Atlas Contact","publish_date":null,"open_library_edition_id":"OL30959815M"}},{"relation":"catalog_edition_metadata","ref":"metadata:9789025440374","key":{"edition_id":969200004},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-10-31T19:31:00Z","review_batch":"nl-followup-003-20261031","evidence":[{"url":"https://metadata.isbn.nl/123962/alles-wat-er-was.html","checkedAt":"2026-10-31","fact":"Exact2013DutchpaperbackISBN/date/cover and source narrative"},{"url":"https://www.bibliotheek.nl/catalogus/titel.423676245.html/alles-wat-er-was/","checkedAt":"2026-10-31","fact":"Library exactISBN/author/original2013print plus explicitly documented2014reissue distinction"},{"url":"https://metadata.isbn.nl/ie_fcache/0000039769_Alles_wat_er_was_0_0.jpg","checkedAt":"2026-10-31T19:30:12.209Z","http":200,"sha256":"88d2e38aa8f826320b10959b653717e6f3ad8aa6334b7e24cf3a59679e9a26f1","bytes":80074,"fact":"Alles wat er was/Hanna Bervoets, black-white nested frames/Atlas Contact; exact2013ISBN block, not Pluim2019art"}],"edition_id":969200004,"work_id":969100004,"bound_author_id":969300004,"bound_title":"Alles wat er was","bound_language":"nld","bound_isbn13":"9789025440374","format":"paperback","cover_url":"https://metadata.isbn.nl/ie_fcache/0000039769_Alles_wat_er_was_0_0.jpg","card_cover_url":null,"evidence_url":"https://metadata.isbn.nl/123962/alles-wat-er-was.html"}},{"relation":"catalog_work_descriptions","ref":"description:1215:nl","key":{"work_id":969100004,"language":"nl"},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-10-31T19:31:00Z","review_batch":"nl-followup-003-20261031","evidence":[{"url":"https://metadata.isbn.nl/123962/alles-wat-er-was.html","checkedAt":"2026-10-31","fact":"Exact2013DutchpaperbackISBN/date/cover and source narrative"},{"url":"https://www.bibliotheek.nl/catalogus/titel.423676245.html/alles-wat-er-was/","checkedAt":"2026-10-31","fact":"Library exactISBN/author/original2013print plus explicitly documented2014reissue distinction"},{"url":"https://metadata.isbn.nl/ie_fcache/0000039769_Alles_wat_er_was_0_0.jpg","checkedAt":"2026-10-31T19:30:12.209Z","http":200,"sha256":"88d2e38aa8f826320b10959b653717e6f3ad8aa6334b7e24cf3a59679e9a26f1","bytes":80074,"fact":"Alles wat er was/Hanna Bervoets, black-white nested frames/Atlas Contact; exact2013ISBN block, not Pluim2019art"}],"work_id":969100004,"language":"nl","bound_author_id":969300004,"text":"Een groep mensen komt in een schoolgebouw bijeen voor televisieopnamen, maar een plotselinge knal onderbreekt hun plannen. Ze moeten binnenblijven en raken afgesloten van de buitenwereld. Merel, een redactrice, beschrijft hoe het alledaagse leven plaatsmaakt voor onzekerheid en een steeds moeizamere verdeling van voedsel en ruimte. Terwijl het wachten voortduurt, veranderen de verhoudingen binnen de groep. De noodsituatie stelt hun onderlinge vertrouwen en hun ideeën over samenleven op de proef.","source_type":"official_catalog","source_name":"Bureau ISBN","source_url":"https://metadata.isbn.nl/123962/alles-wat-er-was.html","provenance":"original_source_reviewed_summary"}}],"bindings":[{"work":{"id":969100001,"title":"Dolfje Weerwolfje","cover_id":null,"author_id":969300001,"work_type":null,"source_type":"open_library","open_library_id":"OL2286363W","first_publish_year":1996,"native_identity_key":null},"author":{"id":969300001,"name":"Paul van Loon","open_library_id":"OL300379A"}},{"work":{"id":969100002,"title":"Revolusi","cover_id":null,"author_id":969300002,"work_type":null,"source_type":"open_library","open_library_id":"OL24234444W","first_publish_year":2020,"native_identity_key":null},"author":{"id":969300002,"name":"David Van Reybrouck","open_library_id":"OL7534049A"}},{"work":{"id":969100003,"title":"Leven en laten leven","cover_id":null,"author_id":969300003,"work_type":null,"source_type":"open_library","open_library_id":"OL34310983W","first_publish_year":2018,"native_identity_key":null},"author":{"id":969300003,"name":"Hendrik Groen","open_library_id":"OL7522010A"}},{"work":{"id":969100004,"title":"Alles wat er was","cover_id":null,"author_id":969300004,"work_type":null,"source_type":"open_library","open_library_id":"OL23118085W","first_publish_year":2013,"native_identity_key":null},"author":{"id":969300004,"name":"Hanna Bervoets","open_library_id":"OL8715660A"}}],"authorCorpora":[]}'::jsonb;a jsonb;b jsonb;actual jsonb;oldrow jsonb;nextrow jsonb;k jsonb;kv record;ids jsonb:='{}';cols text;vals text;v_id bigint;i integer:=0;n integer;begin
 for b in select value from jsonb_array_elements(payload->'bindings') loop
  select to_jsonb(w) into actual from public.works w where id=(b->'work'->>'id')::bigint;
  if actual is distinct from b->'work' and not exists(select 1 from jsonb_array_elements(payload->'actions') p where p->>'relation'='works' and p->'key'=jsonb_build_object('id',(b->'work'->>'id')::bigint) and actual=p->'after') then raise exception 'Work preflight drift';end if;
  select to_jsonb(t) into actual from public.authors t where id=(b->'author'->>'id')::bigint;
  if actual is distinct from b->'author' then raise exception 'Author preflight drift';end if;
 end loop;
 for b in select value from jsonb_array_elements(payload->'authorCorpora') loop
  select coalesce(jsonb_agg(to_jsonb(w) order by id),'[]') into actual from public.works w where author_id=(b->>'author_id')::bigint and not exists(select 1 from jsonb_array_elements(payload->'actions') p where p->>'relation'='works' and p->'before'='null' and w.native_identity_key=p->'after'->>'native_identity_key');
  select coalesce(jsonb_agg(to_jsonb(jsonb_populate_record(null::public.works,value)) order by (value->>'id')::bigint),'[]') into oldrow from jsonb_array_elements(b->'rows');
  select coalesce(jsonb_agg(to_jsonb(jsonb_populate_record(null::public.works,coalesce((select p->'after' from jsonb_array_elements(payload->'actions') p where p->>'relation'='works' and p->'before'<>'null' and p->'key'=jsonb_build_object('id',(v.value->>'id')::bigint)),v.value))) order by (v.value->>'id')::bigint),'[]') into nextrow from jsonb_array_elements(b->'rows') v;
  if actual is distinct from oldrow and actual is distinct from nextrow then raise exception 'New Work author corpus drift; repeat identity review';end if;
 end loop;
 for a in select value from jsonb_array_elements(payload->'actions') loop
  i:=i+1;k:=a->'key';nextrow:=a->'after';oldrow:=a->'before';
  if a->>'relation' not in ('authors','works','editions','catalog_work_descriptions','catalog_edition_metadata') then raise exception 'Unreviewed relation';end if;
  for kv in select * from jsonb_each(nextrow) loop
   if jsonb_typeof(kv.value)='string' and left(kv.value#>>'{}',1)='@' then
    if not ids ? substring(kv.value#>>'{}',2) then raise exception 'Unresolved parent reference';end if;
    nextrow:=jsonb_set(nextrow,array[kv.key],ids->substring(kv.value#>>'{}',2));
   end if;
  end loop;
  for kv in select * from jsonb_each(k) loop
   if jsonb_typeof(kv.value)='string' and left(kv.value#>>'{}',1)='@' then k:=jsonb_set(k,array[kv.key],ids->substring(kv.value#>>'{}',2));end if;
  end loop;
  execute format('select to_jsonb(t) from public.%I t where to_jsonb(t) @> $1 for update',a->>'relation') into actual using k;
  if oldrow<>'null'::jsonb then
   execute format('select to_jsonb(jsonb_populate_record(null::public.%I,$1))',a->>'relation') into oldrow using oldrow;
   execute format('select to_jsonb(jsonb_populate_record(null::public.%I,$1))',a->>'relation') into nextrow using nextrow;
   if actual is not distinct from nextrow then continue;end if;
   if actual is distinct from oldrow then raise exception 'Changed existing row in % at action %',a->>'relation',i;end if;
   select string_agg(format('%I=(jsonb_populate_record(null::public.%I,$1)).%I',key,a->>'relation',key),',') into cols from jsonb_each(nextrow) where value is distinct from oldrow->key;
   execute format('update public.%I t set %s where to_jsonb(t) @> $2 returning to_jsonb(t)',a->>'relation',cols) into actual using nextrow,k;
   insert into catalog_release_receipt values(i,a->>'relation',k,oldrow,actual);
  elsif actual is not null then
   if a->>'relation' in ('catalog_work_descriptions','catalog_edition_metadata') then
    execute format('select to_jsonb(jsonb_populate_record(null::public.%I,$1))',a->>'relation') into nextrow using nextrow;
    if actual is distinct from nextrow then raise exception 'Existing reviewed presentation differs; never overwrite';end if;
   elsif not actual @> nextrow then raise exception 'Existing natural identity differs';end if;
  else
   if a->>'relation'='editions' and exists(select 1 from public.editions e where (nextrow->>'isbn_13' is not null and regexp_replace(coalesce(e.isbn_13,''),'[-[:space:]]','','g')=nextrow->>'isbn_13') or (nextrow->>'isbn_10' is not null and upper(regexp_replace(coalesce(e.isbn_10,''),'[-[:space:]]','','g'))=nextrow->>'isbn_10') or (nextrow->>'open_library_edition_id' is not null and e.open_library_edition_id=nextrow->>'open_library_edition_id')) then raise exception 'Global edition identity collision';end if;
   select string_agg(format('%I',key),',' order by key),string_agg(format('(jsonb_populate_record(null::public.%I,$1)).%I',a->>'relation',key),',' order by key) into cols,vals from jsonb_each(nextrow);
   execute format('insert into public.%I(%s) select %s returning to_jsonb(%I)',a->>'relation',cols,vals,a->>'relation') into actual using nextrow;
   insert into catalog_release_receipt values(i,a->>'relation',k,null,actual);
  end if;
  if actual ? 'id' then ids:=jsonb_set(ids,array[a->>'ref'],actual->'id');end if;
 end loop;
 select count(*) into n from catalog_release_receipt;
 if n not in (0,12) then raise exception 'Partial install/replay; expected zero or all actions, got %',n;end if;
end;$release$;
select jsonb_build_object('project','hlvujbrmfdlrfxdjwsmb','batch','nl079-test-nl-followup-003-20261031','rows',coalesce(jsonb_agg(to_jsonb(r) order by seq),'[]')) as receipt from catalog_release_receipt r;
